		rr, err1 := strconv.ParseUint(s[0:2], 16, 8)
		gg, err2 := strconv.ParseUint(s[2:4], 16, 8)
		bb, err3 := strconv.ParseUint(s[4:6], 16, 8)
		aa, err4 := strconv.ParseUint(s[6:8], 16, 8)
		if err1 != nil || err2 != nil || err3 != nil || err4 != nil {
