package binding

import (
	"fmt"
	"sync"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

type sprintfBind struct {
	base
	format string
	items  []DataItem

	current string
	lastErr error
	lock    sync.RWMutex
}

// NewSprintf creates a formatted string binding that combines multiple data bindings.
// The format string follows fmt.Sprintf conventions. When any source binding changes,
// the formatted string automatically updates.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBind{
		format: format,
		items:  bindings,
	}

	// Listen to all source bindings
	listener := NewDataListener(func() {
		s.update()
	})

	for _, item := range bindings {
		item.AddListener(listener)
	}

	// Initial update
	s.update()

	return s
}

func (s *sprintfBind) update() {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Collect values from all source bindings
	values := make([]interface{}, len(s.items))
	s.lastErr = nil

	for i, item := range s.items {
		var val interface{}
		var err error

		switch typed := item.(type) {
		case Bool:
			val, err = typed.Get()
		case Bytes:
			val, err = typed.Get()
		case Float:
			val, err = typed.Get()
		case Int:
			val, err = typed.Get()
		case Rune:
			val, err = typed.Get()
		case String:
			val, err = typed.Get()
		case URI:
			var u fyne.URI
			u, err = typed.Get()
			if err == nil {
				val = u.String()
			}
		default:
			// Untyped or other binding
			if untyped, ok := item.(Untyped); ok {
				val, err = untyped.Get()
			}
		}

		if err != nil {
			s.lastErr = err
			return
		}

		values[i] = val
	}

	s.current = fmt.Sprintf(s.format, values...)
	s.trigger()
}

func (s *sprintfBind) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.current, s.lastErr
}

func (s *sprintfBind) Set(str string) error {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Parse using fmt.Sscanf
	values := make([]interface{}, len(s.items))

	for i, item := range s.items {
		switch item.(type) {
		case Bool:
			var b bool
			values[i] = &b
		case Bytes:
			// Bytes cannot be round-tripped
			return fmt.Errorf("cannot set Bytes binding from formatted string")
		case Float:
			var f float64
			values[i] = &f
		case Int:
			var n int
			values[i] = &n
		case Rune:
			var r rune
			values[i] = &r
		case String:
			var s string
			values[i] = &s
		case URI:
			var u string
			values[i] = &u
		default:
			var v interface{}
			values[i] = &v
		}
	}

	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.items) {
		return fmt.Errorf("format matched %d values, expected %d", n, len(s.items))
	}

	// Set each source binding
	for i, item := range s.items {
		switch typed := item.(type) {
		case Bool:
			if err := typed.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Float:
			if err := typed.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Int:
			if err := typed.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Rune:
			if err := typed.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case String:
			if err := typed.Set(*values[i].(*string)); err != nil {
				return err
			}
		case URI:
			uriStr := *values[i].(*string)
			u, err := storage.ParseURI(uriStr)
			if err != nil {
				return err
			}
			if err := typed.Set(u); err != nil {
				return err
			}
		}
	}

	return nil
}

func (s *sprintfBind) AddListener(listener DataListener) {
	s.base.AddListener(listener)
}

func (s *sprintfBind) RemoveListener(listener DataListener) {
	s.base.RemoveListener(listener)
}

// StringToStringWithFormat wraps a String binding with a format.
// If the format is "%s" (identity), returns the original binding directly.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

